INSERT INTO `general_config` (`id`, `param_id`, `menu_identify`, `sort`, `values_json`, `ip`, `status`, `enums_type`, `create_by`, `update_by`, `create_time`, `update_time`, `del_flag`) VALUES (136, 'RR002', 'GM025', 1, '{\"enumsValue\":\"HLJZ/2-09-006\",\"menuIdentify\":\"GM025\",\"description\":\"HLJZ/2-09-006修约规则：4舍6入5看右，5后有数进上去，尾数为0向左看，左数奇进偶舍弃：1、“4”舍“6”入：——>例1：将12.1498修约到一位小数，得12.1——>例2：将12.1498修约成两位有效位数，得12。2、“5”看右，5后有数进上去，尾数为0向左看，左数奇进偶舍弃:（1）当尾数为5，而尾数后面的数字均为0时，应看尾数“5”的前一位（1-1）若前一位数字为奇数，就应向前进一位（1-2）若前一位数字为偶数，则应将尾数舍去（1-3）数字“0”在此时应被视为偶数——>例1：将12.6450修约到两位小数，得12.64——>例2：将18.2750修约到两位小数，得18.28（2）当尾数为5，而尾数5的后面还有任何不是0的数字时，无论前一位在此时为奇数还是偶数，也无论5后面不为0的数字在哪一位上，都应向前进一位;——>例1：将12.73507修约到两位小数，得12.74——>例2：将21.84502修约到两位小数，得21.85——>例3：将10.502修约到个位数，得11——>例4：将1268修约到百位数，得13×10²注意：不论数字多少位，都要一次修约成参考文档《2-09-006数字修约管理程序(2022-01).pdf》。\",\"sort\":1,\"paramId\":\"RR002\",\"remark\":null,\"substNo\":null,\"label\":\"《数字修约管理程序》2022-01\",\"value\":null,\"enumsType\":null,\"status\":1,\"unit\":null}', NULL, '1', NULL, '1', '1', '2024-12-11 10:00:12', '2025-01-10 11:57:33', b'0');
